import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  breadcrumbClasses,
  breadcrumbEllipsisClasses,
  breadcrumbItemClasses,
  breadcrumbLinkClasses,
  breadcrumbListClasses,
  breadcrumbPageClasses,
  breadcrumbSeparatorClasses,
} from "./view";

export {
  breadcrumbClasses,
  breadcrumbEllipsisClasses,
  breadcrumbItemClasses,
  breadcrumbLinkClasses,
  breadcrumbListClasses,
  breadcrumbPageClasses,
  breadcrumbSeparatorClasses,
};

/** Inline style object accepted by Foldkit h.Style. */
export type BreadcrumbStyle = Readonly<Record<string, string>>;

/** Root navigation config for the breadcrumb. */
export type RootViewConfig = Readonly<{
  /** Breadcrumb list content. */
  children: readonly Html[];
  /** Accessible label for the navigation landmark. */
  label?: string | undefined;
  /** Additional class names appended after default root className. */
  className?: string | undefined;
  /** Optional inline styles. */
  style?: BreadcrumbStyle | undefined;
}>;

/** List config for breadcrumb ordered items. */
export type ListViewConfig = Readonly<{
  /** Breadcrumb item and separator children. */
  children: readonly Html[];
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

/** Item config for one breadcrumb level. */
export type ItemViewConfig = Readonly<{
  /** Link, page, ellipsis, or custom content. */
  children: readonly Html[];
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

/** Link config for navigable breadcrumb levels. */
export type LinkViewConfig = Readonly<{
  href: string;
  children: readonly (Html | string)[];
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

/** Current-page config for the final breadcrumb item. */
export type PageViewConfig = Readonly<{
  children: readonly (Html | string)[];
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

/** Separator config. */
export type SeparatorViewConfig = Readonly<{
  children?: readonly (Html | string)[] | undefined;
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

/** Ellipsis config for collapsed breadcrumb ranges. */
export type EllipsisViewConfig = Readonly<{
  label?: string | undefined;
  className?: string | undefined;
  style?: BreadcrumbStyle | undefined;
}>;

const cn = (...values: readonly (string | undefined)[]): string =>
  values
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

export const rootView = <ParentMessage>({
  children,
  label = "breadcrumb",
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.nav(
    [
      h.Attribute("aria-label", label),
      h.Class(cn(breadcrumbClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const listView = <ParentMessage>({
  children,
  className,
  style,
}: ListViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.ol(
    [
      h.Class(cn(breadcrumbListClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  children,
  className,
  style,
}: ItemViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.li(
    [
      h.Class(cn(breadcrumbItemClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const linkView = <ParentMessage>({
  href,
  children,
  className,
  style,
}: LinkViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.a(
    [
      h.Href(href),
      h.Class(cn(breadcrumbLinkClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const pageView = <ParentMessage>({
  children,
  className,
  style,
}: PageViewConfig): Html => {
  const h = html<ParentMessage>();
  return h.span(
    [
      h.Attribute("aria-current", "page"),
      h.Class(cn(breadcrumbPageClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const separatorView = <ParentMessage>({
  children = ["›"],
  className,
  style,
}: SeparatorViewConfig = {}): Html => {
  const h = html<ParentMessage>();
  return h.li(
    [
      h.Attribute("aria-hidden", "true"),
      h.Class(cn(breadcrumbSeparatorClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    children
  );
};

export const ellipsisView = <ParentMessage>({
  label = "More",
  className,
  style,
}: EllipsisViewConfig = {}): Html => {
  const h = html<ParentMessage>();
  return h.span(
    [
      h.Attribute("aria-label", label),
      h.Attribute("role", "img"),
      h.Class(cn(breadcrumbEllipsisClasses, className)),
      ...(style === undefined ? [] : [h.Style(style)]),
    ],
    ["..."]
  );
};

export const view = <ParentMessage>(
  items: readonly Readonly<{ label: string; href?: string | undefined }>[],
  separator: string = "›"
): Html =>
  rootView<ParentMessage>({
    children: [
      listView<ParentMessage>({
        children: items.flatMap((item, index) => [
          itemView<ParentMessage>({
            children: [
              item.href === undefined
                ? pageView<ParentMessage>({ children: [item.label] })
                : linkView<ParentMessage>({
                    href: item.href,
                    children: [item.label],
                  }),
            ],
          }),
          ...(index === items.length - 1
            ? []
            : [separatorView<ParentMessage>({ children: [separator] })]),
        ]),
      }),
    ],
  });

export const breadcrumbClasses = "text-sm text-gray-600";

export const breadcrumbListClasses =
  "flex flex-wrap items-center gap-1.5 break-words text-sm text-gray-600";

export const breadcrumbItemClasses = "inline-flex items-center gap-1.5";

export const breadcrumbLinkClasses =
  "rounded-sm text-gray-600 underline-offset-4 transition hover:text-gray-950 hover:underline focus:outline-none focus-visible:ring-2 focus-visible:ring-accent-600";

export const breadcrumbPageClasses = "font-normal text-gray-950";

export const breadcrumbSeparatorClasses =
  "inline-flex items-center text-gray-400 [&>svg]:size-3.5";

export const breadcrumbEllipsisClasses =
  "inline-flex size-9 items-center justify-center rounded-md text-gray-500";

import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { describe, test } from "vitest";

import * as Breadcrumb from "./index";

describe("Breadcrumb registry view", () => {
  test("renders hierarchy links and current page", () => {
    const view = (): Html =>
      Breadcrumb.view<never>([
        { label: "Home", href: "/" },
        { label: "Components", href: "/components" },
        { label: "Breadcrumb" },
      ]);

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("navigation", { name: "breadcrumb" })).toExist(),
      Scene.expect(Scene.role("link", { name: "Home" })).toHaveAttr(
        "href",
        "/"
      ),
      Scene.expect(Scene.text("Breadcrumb")).toHaveAttr("aria-current", "page")
    );
  });

  test("renders ellipsis and custom separator as inert content", () => {
    const view = (): Html =>
      Breadcrumb.rootView<never>({
        children: [
          Breadcrumb.listView<never>({
            children: [
              Breadcrumb.itemView<never>({
                children: [Breadcrumb.ellipsisView<never>()],
              }),
              Breadcrumb.separatorView<never>({ children: ["/"] }),
              Breadcrumb.itemView<never>({
                children: [
                  Breadcrumb.pageView<never>({ children: ["Breadcrumb"] }),
                ],
              }),
            ],
          }),
        ],
      });

    Scene.scene(
      {
        update: (model: undefined): readonly [undefined, []] => [model, []],
        view,
      },
      Scene.with(undefined),
      Scene.expect(Scene.role("img", { name: "More" })).toExist(),
      Scene.expect(Scene.text("/")).not.toHaveHandler("click")
    );
  });
});
